/**
 * The one decision every tool call passes through.
 *
 * A tool body can be reached by more than one path — the model's own calls on
 * a local turn, a cloud turn's calls over the MCP endpoint, a direct
 * `callTool`, the host connection bridge. Each of those is a separate code
 * path, and a guarantee that holds on some of them is not a guarantee. So the
 * decision lives here, in one pure function, and every path asks it rather
 * than re-implementing it.
 */
import { isToolEffect, } from "../types.js";
import { forwardTimeArgument, missingTimeWindow, timeArgViolation } from "./as-of.js";
/**
 * What a stubbed write answers. Deliberately not self-describing: a model told
 * mid-turn that its writes are not real starts hedging its conclusions, and
 * the conclusion is the thing a dry run exists to read. Tell the agent once,
 * in its opening prompt, not in a tool result.
 */
const ACKNOWLEDGED = "Operation acknowledged.";
/**
 * The effect of one specific call.
 *
 * Undeclared resolves to `"write"`. A dry run promises that nothing outside
 * the session changed, and it cannot promise that about a tool it knows
 * nothing about — so the unknown case is the one that costs a stubbed read
 * rather than the one that leaks a real write.
 */
export function resolveEffect(effect, input) {
    const declared = typeof effect === "function"
        ? effect(
        // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- effect's input is erased to never so an authored effect stays assignable
        input)
        : effect;
    // Undeclared and malformed stay writes. `idempotent` is kept: collapsing
    // it to `"write"` would hide the one non-read effect retry accepts.
    return isToolEffect(declared) ? declared : "write";
}
/**
 * The effect an MCP server's own annotations declare, fail-closed.
 *
 * `readOnlyHint: true` without `destructiveHint: true` is a read, even when
 * `idempotentHint` is also set. `idempotentHint` and `destructiveHint` are
 * otherwise orthogonal: `idempotentHint: true` with `destructiveHint`
 * explicitly true or explicitly false is `idempotent` (a DELETE, a
 * replacing put, or drop-if-exists can be both destructive and safe to
 * repeat). Omitted `destructiveHint` is neither true nor false, so a bare
 * `idempotentHint` stays unclassified. `destructiveHint: true` without
 * `idempotentHint`, and `destructiveHint: false` without `idempotentHint`,
 * are writes. `readOnlyHint: false` without an idempotent classification
 * is a write. Absent annotations, or annotations that carry no effect
 * signal (a bare `title`), are unclassified.
 *
 * `idempotent` is not a read and is not "non-destructive". Approval and a
 * destructive warning keep reading `destructiveHint`.
 *
 * Read-risk classification in `@anysphere/mcp-core/mcp-tool-annotations`
 * (`classifyMcpToolAnnotationRisk`) stays a read-versus-write signal. This
 * package cannot import it (npm publish, workspace-only dependency). An
 * idempotent call is not a read there either.
 */
export function classifyAnnotationsEffect(annotations) {
    if (annotations === undefined) {
        return undefined;
    }
    if (annotations.readOnlyHint === true && annotations.destructiveHint !== true) {
        return "read";
    }
    if (annotations.idempotentHint === true &&
        (annotations.destructiveHint === true || annotations.destructiveHint === false)) {
        return "idempotent";
    }
    if (annotations.destructiveHint === true ||
        annotations.destructiveHint === false ||
        annotations.readOnlyHint === false) {
        return "write";
    }
    return undefined;
}
/**
 * The effect of one direct call on a discovered tool, the same way
 * {@link decideToolCall} reads it: the authored declaration when there is
 * one (possibly per input), else the MCP server's own annotations for an
 * advertised passthrough. `undefined` is an advertised tool nothing
 * classifies; callers gating on "read" treat it as a write.
 */
export function directCallEffect(tool, input) {
    if (tool.definition.effect === undefined && tool.advertised === true) {
        return classifyAnnotationsEffect(tool.annotations);
    }
    return resolveEffect(tool.definition.effect, input);
}
/**
 * What a dry run answers when nothing classifies an MCP tool. Deliberately
 * reads as a strict API rather than disclosing the session's posture (see
 * {@link ACKNOWLEDGED}), and names what is missing so the fix — the server
 * annotating, or a server-side classification entry — is one step away.
 */
function unclassifiedRefusal(toolName) {
    return (`Tool "${toolName}" is not available in this session: its MCP server ` +
        `does not declare whether it reads or writes (readOnlyHint/` +
        `destructiveHint), and no server-side classification exists for it, so ` +
        `this session cannot tell whether calling it would change anything ` +
        `outside the session. Use a tool that declares its effect.`);
}
/** Decide what to do with one tool call. Pure; no I/O, no session state. */
export function decideToolCall(facts) {
    // Before the dry-run split: a frozen session bounds its reads whether or
    // not its writes are stubbed.
    if (facts.asOf !== undefined) {
        if (facts.timeArgs !== undefined && facts.timeArgs.length > 0) {
            const violation = timeArgViolation(facts.input, facts.timeArgs, facts.asOf);
            if (violation !== undefined) {
                return { kind: "unbounded", message: violation };
            }
        }
        const forward = forwardTimeArgument(facts.input, facts.asOf);
        if (forward !== undefined) {
            return { kind: "unbounded", message: forward };
        }
        // Present values are checked above; absent ones are the vendor's live
        // default window, which no walker can see. Require them explicitly.
        if (facts.timeWindow !== undefined) {
            const omitted = missingTimeWindow(facts.input, facts.timeWindow, facts.asOf);
            if (omitted !== undefined) {
                return { kind: "unbounded", message: omitted };
            }
        }
    }
    if (!facts.dryRun) {
        return { kind: "run" };
    }
    if (facts.effect === undefined && facts.mcpTool !== undefined) {
        const effect = classifyAnnotationsEffect(facts.mcpTool.annotations);
        if (effect === undefined) {
            return {
                kind: "refuse",
                message: unclassifiedRefusal(facts.mcpTool.name),
            };
        }
        if (effect === "read") {
            return { kind: "run" };
        }
        return {
            kind: "answer",
            result: dryRunAnswer(facts.dryRunResult, facts.input),
        };
    }
    if (resolveEffect(facts.effect, facts.input) === "read") {
        return { kind: "run" };
    }
    return {
        kind: "answer",
        result: dryRunAnswer(facts.dryRunResult, facts.input),
    };
}
function dryRunAnswer(dryRunResult, input) {
    if (dryRunResult === undefined) {
        return ACKNOWLEDGED;
    }
    if (typeof dryRunResult === "function") {
        return dryRunResult(
        // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- dry-run input is erased to never so an authored result stays assignable
        input);
    }
    return dryRunResult;
}
